fn all_digits(s: Str) -> Bool {
  if s.is_empty() {
    return false
  }
  for c in s.codes() {
    if c < 48 or c > 57 {
      return false
    }
  }
  return true
}

fn is_lower_name(s: Str) -> Bool {
  if s.is_empty() {
    return false
  }
  for c in s.codes() {
    if c < 97 or c > 122 {
      return false
    }
  }
  return true
}

fn is_int_text(s: Str) -> Bool {
  var body = s
  if s.starts_with("-") {
    body = s.slice(1, s.len())
  }
  return all_digits(body)
}

fn is_term(s: Str) -> Bool {
  return is_int_text(s) or is_lower_name(s)
}

fn line_ok(parts: List[Str]) -> Bool {
  let n = parts.len()
  if n < 3 or (n - 3) % 2 != 0 {
    return false
  }
  if is_lower_name(parts.get_or(0, "")) == false {
    return false
  }
  if parts.get_or(1, "") != "=" {
    return false
  }
  var k = 2
  while k < n {
    if is_term(parts.get_or(k, "")) == false {
      return false
    }
    if k + 1 < n {
      let op = parts.get_or(k + 1, "")
      if op != "+" and op != "-" {
        return false
      }
    }
    k = k + 2
  }
  return true
}

fn value_of(vars: Map[Str, Int], t: Str) -> Int {
  if is_lower_name(t) {
    return vars.get(t).unwrap_or(0)
  }
  return t.to_int().unwrap_or(0)
}

pub fn run_vars(lines: List[Str]) -> Result[Map[Str, Int], Str] {
  var vars: Map[Str, Int] = Map {}
  for line in lines {
    let parts = line.split(" ")
    if line_ok(parts) == false {
      return Err("syntax error")
    }
    var acc = 0
    var op = "+"
    var k = 2
    while k < parts.len() {
      let t = parts.get_or(k, "")
      if is_lower_name(t) and vars.has(t) == false {
        return Err("undefined " + t)
      }
      let v = value_of(vars, t)
      if op == "+" {
        acc = acc + v
      } else {
        acc = acc - v
      }
      op = parts.get_or(k + 1, "+")
      k = k + 2
    }
    vars = vars.set(parts.get_or(0, ""), acc)
  }
  return Ok(vars)
}
